/// Font family names a skin bundles, by role. `nil` means the system face.
struct SkinTypeface: Equatable, Sendable {
    /// largeTitle · title · title2 · title3 · headline, and navigation titles.
    let display: String?
    /// Chips, badges — small categorical labels, never body copy or data.
    let label: String?
    /// Multiplies the display face's point size: a face set wide (a pixel
    /// face) needs less than the style's size to fit the same line.
    var displayScale: CGFloat = 1
}

/// The L1 status roles. A closed set — see `design-system/README.md`.
enum SemanticRole: CaseIterable, Sendable {
    case danger
    case caution
    case success
    case info
}

/// `text` is small copy (gated 4.5:1); `accent` is a standalone mark (3:1).
enum SemanticVariant: CaseIterable, Sendable {
    case text
    case accent
}

// MARK: - Decorations

/// A skin's decoration set: the scene `SkinBackdrop` draws behind every
/// screen, the glyph stickers it scatters over it, the pair that sits on a
/// glance card's corners, and the one that floats up from a tap.
struct SkinDecorations: Sendable {
    let scene: SkinScene
    /// Stickers scattered over the scene. Empty for none.
    let glyphs: [SkinGlyph]
    /// (top-right, bottom-left) on the large cards. `nil` for none.
    let frameCorners: (SkinGlyph, SkinGlyph)?
    /// Spawned at every tap by `TapTrail`. `nil` for none.
    let tapGlyph: SkinGlyph?
}

/// What `SkinBackdrop` paints under the stickers.
enum SkinScene: Sendable {
    /// ely.pink: a warm glow at the top and a faint dotted ground; the
    /// stickers carry the scene.
    case stickers

    var isStickers: Bool {
        if case .stickers = self { true } else { false }
    }

    var isArcade: Bool {
        if case .arcade = self { true } else { false }
    }
    /// A night sky: a twinkling, haloed starfield over nebula glows.
    case nightSky(SkinNightSky)
    /// Deep water: a depth gradient, light rays, rising bubbles, and
    /// jellyfish swimming up.
    case underwater(SkinUnderwater)
    /// Washi paper, raked sand around stones, sakura petals.
    case paper(SkinPaperGarden)
    /// A dark meadow: fireflies, fog, a tree line, an aurora.
    case fireflies(SkinFireflies)
    /// Falling snow and frost at the corners.
    case snow(SkinSnow)
    /// A perspective neon grid, pixel stars, a snake.
    case arcade(SkinArcade)
    /// A sky that follows the real time of day and season.
    case sky(SkinSky)
    /// dose.wiki: their page halos and their molecule ring, faint and slow.
    case molecule(SkinMolecule)
    /// Hanabi: a festival night — a static star field, then rockets that rise
    /// on a fading trail and burst in the game's five suits.
    case fireworks(SkinFireworks)
    /// Selenia: an engraved chart wheel turning under a faint dome.
    case ephemeris(SkinEphemeris)
    /// Gatsby: a supercar under a skyline — at night in dark mode, at dusk in
    /// light. Still.
    case nocturne(SkinNocturne)
    /// Irie: a velvet ground, the tricolor as a pinstripe, embossed fan
    /// leaves. Still.
    case velvet(SkinVelvet)

    /// A picture a pushed screen or a sheet covers with stained glass: it
    /// belongs to the tab roots, and copy does not read over it.
    var veilsDepth: Bool {
        if case .nocturne = self { true } else { false }
    }

    /// Drawn once and never ticked: the vanity scenes are pictures, not
    /// animations, and cost nothing after the first frame.
    var isStill: Bool {
        switch self {
        case .nocturne, .velvet: true
        case .stickers, .nightSky, .underwater, .paper, .fireflies, .snow, .arcade, .sky, .molecule, .fireworks, .ephemeris: false
        }
    }
}

struct SkinNocturne: Sendable {
    /// The dark-mode picture and the light-mode one, resolved in the renderer
    /// like dose.wiki's ring.
    let night: ImageResource
    let dusk: ImageResource
    /// The scrim's color: the skin's background.
    let ground: Color
}

struct SkinVelvet: Sendable {
    /// Red, gold, green: the pinstripe, top band first.
    let stripes: [Color]
    /// The embossed leaves' shadow side and lit side.
    let leafShade: Color
    let leafLight: Color
    /// The two leaves drawn in gold outline.
    let gold: Color
}

extension SkinGilding {
    /// Chrome-style lettering, top to bottom: bright, a sheen, then a hard
    /// horizon where the reflection breaks, and the foot lit again from below.
    var titleStops: [Gradient.Stop] {
        [
            .init(color: bright, location: 0),
            .init(color: shine, location: 0.28),
            .init(color: mid, location: 0.5),
            .init(color: deep, location: 0.52),
            .init(color: mid, location: 0.78),
            .init(color: bright, location: 1),
        ]
    }
}

/// A gilded button's metal. The foil ramp runs deep → mid → bright → shine;
/// `ink` is the label set on it, gated 4.5:1 against `mid` by
/// `ColorContrastTests`.
struct SkinGilding: Sendable {
    let deep: Color
    let mid: Color
    let bright: Color
    let shine: Color
    let ink: Color
    /// A pinstripe along the foot of a prominent button, left to right.
    /// Empty for none.
    let stripe: [Color]
}

/// Selenia's chart wheel: concentric rules, twelve sign sectors and the
/// aspect chords across the middle.
struct SkinEphemeris: Sendable {
    let ink: Color
    let ring: Color
    let star: Color
    /// fire, earth, air, water, in that order, for the sector ticks.
    let elements: [Color]
}

/// Hanabi's night. The five suits are the game's own `Theme.cardColor`
/// values at full saturation — art, not UI roles, so they are never gated.
struct SkinFireworks: Sendable {
    let suits: [Color]
    /// The white core every burst ends on, and the rocket's trail.
    let spark: Color
    /// The menu's static 50-star field behind everything.
    let star: Color
}

struct SkinMolecule: Sendable {
    /// The ring: their mark as a template image, resolved here on the main
    /// actor because the renderer is not.
    let image: ImageResource
    /// The ring is tinted with this.
    let ink: Color
    /// The site's page halos, top / left / right / bottom.
    let halos: [SkinGlow]
}

struct SkinPaperGarden: Sendable {
